// Code v2 — JavaScript — Run Once for All Items
const inputs = $input.all();

const classificationFields = [
  'original_language',
  'sentiment',
  'strength',
  'confidence',
];

const editorialFields = [
  'content_type',
  'topics',
  'relevance_score',
  'summary',
  'suggested_route',
  'needs_human_review',
  'assessment_note',
];

const languages = new Set(['pt', 'es', 'en', 'other']);

const sentiments = new Set([
  'Excited',
  'Happy',
  'Neutral',
  'Disappointed',
  'Angry',
]);

const contentTypes = new Set([
  'technical_answer',
  'job_achievement',
  'testimonial',
  'technical_question',
  'course_feedback',
  'debate',
  'noise',
]);

const routes = new Set([
  'success_case',
  'faq',
  'newsletter_only',
  'moderation',
  'discard',
]);

const outputFields = [
  'source_id',
  'source',
  'answers',
];

const answerOutputFields = [
  'answer_id',
  ...classificationFields,
  ...editorialFields,
];

function fail(message) {
  throw new Error(`Merge Classification: ${message}`);
}

function hasOwn(value, field) {
  return Object.prototype.hasOwnProperty.call(value, field);
}

function object(value, label) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    fail(`${label}: objeto inválido`);
  }

  return value;
}

function nonEmptyString(value, label) {
  if (typeof value !== 'string' || value.trim() === '') {
    fail(`${label}: string vazia ou inválida`);
  }

  return value;
}

function exactFields(value, expectedFields, label) {
  const allowed = new Set(expectedFields);

  const missing = expectedFields.filter(
    field => !hasOwn(value, field)
  );

  const extra = Object.keys(value).filter(
    field => !allowed.has(field)
  );

  if (missing.length || extra.length) {
    fail(
      `${label}: campos ausentes=[${missing.join(', ')}]; ` +
      `campos não permitidos=[${extra.join(', ')}]`
    );
  }
}

function sourceId(value, label) {
  if (typeof value === 'number' && Number.isSafeInteger(value)) {
    return String(value);
  }

  if (typeof value === 'string' && value.trim() !== '') {
    return value;
  }

  fail(`${label}: source_id ausente ou inválido`);
}

function answerId(value, label) {
  // Normaliza somente a chave de comparação.
  // O valor original será preservado no resultado.
  if (
    typeof value === 'number' &&
    Number.isSafeInteger(value) &&
    value > 0
  ) {
    return String(value);
  }

  if (typeof value === 'string' && /^[1-9]\d*$/.test(value)) {
    return value;
  }

  fail(`${label}: answer_id ausente ou inválido`);
}

function indexAnswers(value, label) {
  if (!Array.isArray(value)) {
    fail(`${label}: answers não é array`);
  }

  const index = new Map();

  value.forEach((answer, position) => {
    const answerLabel = `${label}.answers[${position}]`;

    object(answer, answerLabel);

    const key = answerId(answer.answer_id, answerLabel);

    if (index.has(key)) {
      fail(`${label}: answer_id duplicado ${key}`);
    }

    index.set(key, answer);
  });

  return index;
}

function sameIds(left, right, label) {
  const missing = [...left.keys()].filter(id => !right.has(id));
  const extra = [...right.keys()].filter(id => !left.has(id));

  if (missing.length || extra.length) {
    fail(
      `${label}: ausentes=[${missing.join(', ')}]; ` +
      `sem correspondência=[${extra.join(', ')}]`
    );
  }
}

function unitInterval(value, label) {
  if (
    typeof value !== 'number' ||
    !Number.isFinite(value) ||
    value < 0 ||
    value > 1
  ) {
    fail(`${label}: deve ser um número entre 0 e 1`);
  }
}

function validateTopics(value, label) {
  if (!Array.isArray(value) || value.length > 5) {
    fail(`${label}: deve ser um array com até cinco tópicos`);
  }

  const seen = new Set();

  value.forEach((topic, position) => {
    nonEmptyString(topic, `${label}[${position}]`);

    // Detecta repetições textuais, desconsiderando caixa e espaços.
    // Sinônimos ainda dependem da avaliação editorial.
    const key = topic
      .normalize('NFKC')
      .trim()
      .replace(/\s+/g, ' ')
      .toLocaleLowerCase('pt-BR');

    if (seen.has(key)) {
      fail(`${label}: tópico duplicado na posição ${position}`);
    }

    seen.add(key);
  });
}

function validateClassification(classification, id) {
  const label = `resposta ${id}`;

  exactFields(classification, answerOutputFields, label);

  if (
    !Number.isSafeInteger(classification.answer_id) ||
    classification.answer_id <= 0
  ) {
    fail(`${label}: output exige answer_id inteiro positivo`);
  }

  if (!languages.has(classification.original_language)) {
    fail(`${label}: original_language inválido`);
  }

  if (!sentiments.has(classification.sentiment)) {
    fail(`${label}: sentiment inválido`);
  }

  unitInterval(classification.strength, `${label}.strength`);
  unitInterval(classification.confidence, `${label}.confidence`);

  if (!contentTypes.has(classification.content_type)) {
    fail(`${label}: content_type inválido`);
  }

  validateTopics(classification.topics, `${label}.topics`);

  if (
    !Number.isInteger(classification.relevance_score) ||
    classification.relevance_score < 0 ||
    classification.relevance_score > 100
  ) {
    fail(`${label}: relevance_score deve ser inteiro entre 0 e 100`);
  }

  nonEmptyString(classification.summary, `${label}.summary`);

  if (!routes.has(classification.suggested_route)) {
    fail(`${label}: suggested_route inválido`);
  }

  if (typeof classification.needs_human_review !== 'boolean') {
    fail(`${label}: needs_human_review deve ser boolean`);
  }

  nonEmptyString(
    classification.assessment_note,
    `${label}.assessment_note`
  );

  if (
    classification.content_type === 'noise' &&
    classification.suggested_route !== 'discard'
  ) {
    fail(`${label}: content_type noise exige suggested_route discard`);
  }

  if (
    classification.suggested_route === 'moderation' &&
    classification.needs_human_review !== true
  ) {
    fail(`${label}: rota moderation exige needs_human_review true`);
  }
}

return inputs.map((item, i) => {
  let original;
  let sent;

  try {
    original = $('Filter').itemMatching(i).json;
    sent = $('Limit').itemMatching(i).json;
  } catch (error) {
    fail(`item ${i}: item linking indisponível ou ambíguo`);
  }

  object(original, `item ${i}: original`);
  object(sent, `item ${i}: entrada do agente`);

  let result = item.json.output;

  if (typeof result === 'string') {
    try {
      result = JSON.parse(result);
    } catch (error) {
      fail(`item ${i}: output não contém JSON válido`);
    }
  }

  object(result, `item ${i}: output`);
  exactFields(result, outputFields, `item ${i}: output`);

  // O parser exige source_id string na saída do agente.
  nonEmptyString(result.source_id, `item ${i}: output.source_id`);

  const expectedId = sourceId(sent.source_id, 'entrada do agente');

  if (
    sourceId(original.source_id, 'original') !== expectedId ||
    sourceId(result.source_id, 'output') !== expectedId
  ) {
    fail(`item ${i}: source_id divergente`);
  }

  if (
    sent.source !== 'stackoverflow' ||
    result.source !== sent.source
  ) {
    fail(`item ${i}: source divergente`);
  }

  if (
    hasOwn(original, 'source') &&
    original.source !== sent.source
  ) {
    fail(`item ${i}: source original divergente`);
  }

  // source_file é proveniência obtida da preparação da entrada,
  // nunca um campo fornecido pelo modelo.
  if (hasOwn(sent, 'source_file')) {
    nonEmptyString(
      sent.source_file,
      `item ${i}: entrada do agente.source_file`
    );

    if (
      hasOwn(original, 'source_file') &&
      original.source_file !== sent.source_file
    ) {
      fail(`item ${i}: source_file original divergente`);
    }
  }

  const originals = indexAnswers(original.answers, 'original');
  const sentAnswers = indexAnswers(sent.answers, 'entrada do agente');
  const classifications = indexAnswers(result.answers, 'output');

  sameIds(
    originals,
    sentAnswers,
    'original versus entrada do agente'
  );

  sameIds(
    originals,
    classifications,
    'original versus output'
  );

  for (const [id, classification] of classifications) {
    validateClassification(classification, id);
  }

  // Clona dados JSON para não modificar os objetos anteriores.
  const merged = JSON.parse(JSON.stringify(original));

  merged.source = sent.source;

  if (hasOwn(sent, 'source_file')) {
    merged.source_file = sent.source_file;
  }

  for (const answer of merged.answers) {
    const id = answerId(answer.answer_id, 'original');
    const classification = classifications.get(id);

    // Impede sobrescrever uma avaliação anterior ou deixar
    // campos editoriais antigos conflitantes na raiz da resposta.
    const reservedFields = [
      ...classificationFields,
      ...editorialFields,
      'editorial',
      'routing',
    ];

    for (const field of reservedFields) {
      if (hasOwn(answer, field)) {
        fail(`resposta ${id}: campo ${field} já existe no original`);
      }
    }

    for (const field of classificationFields) {
      answer[field] = classification[field];
    }

    answer.editorial = {};

    for (const field of editorialFields) {
      const value = classification[field];

      answer.editorial[field] = Array.isArray(value)
        ? [...value]
        : value;
    }
  }

  return {
    json: merged,
    pairedItem: { item: i },
  };
});
